exports.declaration:
export interface CapabilityClient {
    load(signal: AbortSignal): Promise<CapabilitySummary>;
}

export interface CapabilitySummary {
    readonly schemaVersion: '1.0.0';
    readonly supportedContractVersions: readonly [
        '1.0.0',
        ...string[]
    ];
    readonly engineMode: LocalEngineMode;
    readonly formatCount: number;
    readonly availableDetectorCount: number;
    readonly maximumInputBytes: number;
    readonly supportedFiles: readonly SupportedFileFormat[];
    readonly supportedEntityTypes: readonly CommonEntityTypeContract.EntityType[];
}

export interface DetectionPageSummary {
    readonly jobId: string;
    readonly jobRevision: number;
    readonly detections: number;
    readonly conflicts: number;
    readonly byEntity: Readonly<Partial<Record<PreviewEntityType, number>>>;
    readonly cursor: number;
    readonly nextCursor: number | null;
    readonly details: readonly JobDetectionSummary[];
    readonly conflictDetails: readonly PreviewConflictSummary[];
    readonly conflictDetailsLimited: boolean;
}

export interface JobDetectionSummary extends PreviewDetectionSummary {
    readonly id: string;
}

export interface JobEventPageSummary {
    readonly jobId: string;
    readonly nextCursor: number;
    readonly events: readonly JobEventSummary[];
}

export interface JobEventSummary {
    readonly id: string;
    readonly cursor: number;
    readonly revision: number;
    readonly type: JobEventType;
    readonly occurredAt: string;
    readonly counts?: Readonly<Record<string, number>>;
}

export interface JobStatusSummary {
    readonly id: string;
    readonly operation: JobOperation;
    readonly state: JobState;
    readonly revision: number;
    readonly policy: Readonly<Pick<PolicyReference, 'id' | 'version' | 'digest'>>;
    readonly createdAt: string;
    readonly updatedAt: string;
}

export interface LocalApiSession {
    readonly apiOrigin: string;
    readonly bearerToken: string;
}

export interface LocalJobClient {
    loadPolicies(signal: AbortSignal): Promise<PolicyCatalogSummary>;
    scan(file: File, policy: PolicyReference, onProgress: (state: ScanProgressState) => void, signal: AbortSignal): Promise<ProcessingScanSummary>;
    redact(file: File, policy: PolicyReference, review: ReviewSetSummary, onProgress: (state: ScanProgressState) => void, signal: AbortSignal): Promise<ProcessingRedactionSummary>;
    listDetections(jobId: string, cursor: number, limit: number, signal: AbortSignal): Promise<DetectionPageSummary>;
    getReviewSet(jobId: string, signal: AbortSignal): Promise<ReviewSetSummary>;
    appendReviewDecisions(jobId: string, expectedJobRevision: number, expectedExtractionRevision: string, expectedReviewRevision: number, decisions: readonly ReviewDecisionInput[], signal: AbortSignal): Promise<ReviewSetSummary>;
    scanPreview(file: File, signal: AbortSignal): Promise<PreviewScanSummary>;
    create(operation: JobOperation, policy: PolicyReference, idempotencyKey: string, signal: AbortSignal): Promise<JobStatusSummary>;
    get(jobId: string, signal: AbortSignal): Promise<JobStatusSummary>;
    listEvents(jobId: string, afterCursor: number, limit: number, signal: AbortSignal): Promise<JobEventPageSummary>;
    cancel(jobId: string, expectedRevision: number, signal: AbortSignal): Promise<JobStatusSummary>;
    expire(jobId: string, signal: AbortSignal): Promise<void>;
}

export interface LocalSessionClient {
    readonly capabilities: CapabilityClient;
    readonly jobs: LocalJobClient;
}

export interface PolicyCatalogSummary {
    readonly defaultPolicy: PolicyReference;
    readonly policies: readonly PolicyReference[];
}

export interface PolicyReference {
    readonly id: string;
    readonly version: string;
    readonly digest: string;
    readonly riskTier: 'LOW' | 'MODERATE' | 'HIGH';
    readonly example: boolean;
}

export interface PreviewConflictSummary {
    readonly code: 'INCOMPATIBLE_OVERLAP';
    readonly start: number;
    readonly end: number;
    readonly entityTypes: readonly PreviewEntityType[];
    readonly sources: readonly PreviewDetectionSource[];
}

export interface PreviewDetectionSummary {
    readonly entityType: PreviewEntityType;
    readonly start: number;
    readonly end: number;
    readonly confidence: number;
    readonly sources: readonly PreviewDetectionSource[];
}

export interface PreviewScanSummary {
    readonly outcome: PreviewOutcome;
    readonly detections: number;
    readonly conflicts: number;
    readonly byEntity: Readonly<Partial<Record<PreviewEntityType, number>>>;
    readonly details: readonly PreviewDetectionSummary[];
    readonly detailsLimited: boolean;
    readonly conflictDetails: readonly PreviewConflictSummary[];
    readonly conflictDetailsLimited: boolean;
}

export interface ProcessingRedactionSummary {
    readonly job: JobStatusSummary;
    readonly output: RedactedOutputSummary;
}

export interface ProcessingScanSummary extends DetectionPageSummary {
    readonly outcome: PreviewOutcome;
    readonly job: JobStatusSummary;
    readonly events: readonly JobEventSummary[];
    readonly review: ReviewSetSummary;
}

export interface RedactedOutputSummary {
    readonly id: string;
    readonly mediaType: 'text/plain' | 'text/markdown';
    readonly byteLength: number;
    readonly digest: string;
    readonly displayName: 'document.redacted.txt' | 'document.redacted.md';
    readonly bytes: Uint8Array;
}

export interface ReviewSetSummary {
    readonly schemaVersion: '1.0.0';
    readonly jobId: string;
    readonly jobRevision: number;
    readonly extractionRevision: string;
    readonly reviewRevision: number;
    readonly digest: string;
    readonly decisions: readonly ReviewDecisionSummary[];
}

export interface SupportedFileFormat {
    readonly extension: string;
    readonly maximumInputBytes: number;
    readonly supportsRedaction: boolean;
}
